-- 계획 수를 비교한다

@Test
@Transactional
void 문장_종류() {
    Set<Integer> sizes = new HashSet<>();
    for (int n = 1; n <= 100; n++) sizes.add(n);

    Set<Integer> padded = new HashSet<>();
    for (int n = 1; n <= 100; n++) {
        int p = Integer.highestOneBit(n);
        padded.add(p == n ? n : p * 2);
    }

    System.out.println("패딩 없이: " + sizes.size() + "종");
    System.out.println("패딩 있으면: " + padded.size() + "종");
}

패딩 없이: 100종
패딩 있으면: 7종

--   100 가지가 7 가지가 됐다


