-- 호출 전에 막는다

default List<Member> byNamesSafe(Collection<String> names) {
    if (names == null || names.isEmpty()) return List.of();
    return byNames(names);
}

@Test
@Transactional
void 막으면() {
    em.clear();
    long n = counter.count(() ->
            memberRepository.byNamesSafe(List.of()));
    System.out.println("쿼리 " + n + "개");
}

